 15→export function buildAdvisorRecs(
 16→  decision: ActiveDecision,
 17→  roles: Pick<RoleDef, "id" | "label">[],
 18→): AdvisorRecommendation[] {
 19→  const recs = decision.recommendations || {};
 20→  return Object.entries(recs).map(([key, oid]) => {
 21→    const colonIdx = key.indexOf(":");
 22→    if (colonIdx !== -1) {
 23→      const roleId = key.slice(colonIdx + 1);
 24→      const roleInfo = roles.find((r) => r.id === roleId);
 25→      return {
 26→        participantId: key,
 27→        participantName: roleInfo?.label ?? roleId,
 28→        optionId: oid,
 29→      };
 30→    }
 31→    return { participantId: key, participantName: key, optionId: oid };
 32→  });
 33→}
 34→
 35→export function getScenarioAdvisorRoles(
 36→  roles: RoleDef[],
 37→): Pick<RoleDef, "id" | "label">[] {
 38→  return roles.filter((r) => r.player_type === "advisor");
 39→}
