 41→export function submitRecommendation(
 42→  api: DecisionApiService,
 43→  exerciseId: number,
 44→  decision: ActiveDecision,
 45→  participantId: string,
 46→  event: SubmitEvent,
 47→): void {
 48→  const optionId = event.selectedOptions[0];
 49→  if (!optionId) return;
 50→  api
 51→    .submitRecommendation(exerciseId, decision.id, optionId, participantId)
 52→    .subscribe();
 53→}
 54→
 55→export function submitRoleRecommendation(
 56→  api: DecisionApiService,
 57→  exerciseId: number,
 58→  decision: ActiveDecision,
 59→  participantId: string,
 60→  rec: RoleRecommendation,
 61→): void {
 62→  const optionId = rec.selectedOptions[0];
 63→  if (!optionId) return;
 64→  api
 65→    .submitRecommendation(
 66→      exerciseId,
 67→      decision.id,
 68→      optionId,
 69→      participantId,
 70→      rec.roleId,
 71→    )
 72→    .subscribe();
 73→}
 74→
 75→export function submitDecision(
 76→  api: DecisionApiService,
 77→  store: InstanceType<typeof ExerciseStore>,
 78→  exerciseId: number,
 79→  decision: ActiveDecision,
 80→  event: SubmitEvent,
 81→): void {
 82→  api
 83→    .closeEngineDecision(exerciseId, decision.id, event.selectedOptions)
 84→    .subscribe({
 85→      next: () => store.closeDecision(decision.id),
 86→    });
 87→}
 88→
 89→export function resolvePlayerRole(
 90→  ctx: ScenarioContext,
 91→  role: string,
 92→  gameMode: string,
 93→  store: InstanceType<typeof ExerciseStore>,
 94→  roleLabel: WritableSignal<string>,
 95→  domain: DomainService,
 96→): void {
 97→  store.setContext(ctx);
 98→  if (!gameMode && ctx.roles && ctx.roles.length > 0) {
 99→    store.setGameMode("simple_collaborative");
100→  }
101→  const roleInfo = ctx.roles?.find((r) => r.id === role);
102→  if (roleInfo) {
103→    store.setPlayerType(roleInfo.player_type);
104→    roleLabel.set(roleInfo.label);
105→  } else if (role === "all_advisors") {
106→    store.setPlayerType("advisor");
107→    roleLabel.set(domain.term("advisor") + "s");
108→  } else if (role === "decision_maker") {
109→    store.setPlayerType("decision_maker");
110→    roleLabel.set(domain.term("decisionMaker"));
111→  } else if (role === "solo_player") {
112→    store.setPlayerType("decision_maker");
113→    roleLabel.set("Solo Player");
114→  }
115→}
