 21→
 22→@Component({
 23→  selector: "tfc-role-card",
 24→  changeDetection: ChangeDetectionStrategy.OnPush,
 25→  imports: [UpperCasePipe, BadgeComponent, ButtonDirective],
 26→  template: `
 27→    <div
 28→      class="role-card"
 29→      [class.role-card--intel]="card().status === 'intel'"
 30→      [class.role-card--active]="card().status === 'active'"
 31→      [class.role-card--done]="card().status === 'done'"
 32→    >
 33→      <!-- Header -->
 34→      <div class="role-card__header">
 35→        <span class="role-card__role-id">{{ card().roleId | uppercase }}</span>
 36→        <ui-badge
 37→          [variant]="card().status === 'active' ? 'default' : 'secondary'"
 38→        >
 39→          {{ badgeLabel() }}
 40→        </ui-badge>
 41→      </div>
 42→      <div class="role-card__role-label">{{ card().roleLabel }}</div>
 43→
 44→      <!-- Intel -->
 45→      @if (card().intel) {
 46→        <div class="role-card__intel">{{ card().intel }}</div>
 47→      } @else if (card().decision) {
 48→        <div class="role-card__intel role-card__intel--empty">
 49→          No role-specific intel this turn
 50→        </div>
 51→      }
 52→
 53→      <!-- Advisor Recs (CO card only) -->
 54→      @if (card().advisorRecs.length > 0) {
 55→        <div class="role-card__recs">
 56→          <div class="role-card__recs-title">Advisor Recommendations</div>
 57→          @for (rec of card().advisorRecs; track rec.roleId) {
 58→            <div
 59→              class="role-card__rec"
 60→              [class.role-card__rec--pending]="!rec.selection"
 61→            >
 62→              <span class="role-card__rec-role">{{ rec.roleLabel }}:</span>
 63→              @if (rec.selection) {
 64→                <span class="role-card__rec-selection">{{
 65→                  rec.selection
 66→                }}</span>
 67→              } @else {
 68→                <span class="role-card__rec-pending">pending...</span>
 69→              }
 70→            </div>
 71→          }
 72→        </div>
 73→      }
 74→
 75→      <!-- Decision Form (active only) -->
 76→      @if (card().decision && card().status === "active") {
 77→        <div class="role-card__decision">
 78→          @if (
 79→            questionType() === "single_choice" ||
 80→            questionType() === "multi_choice"
 81→          ) {
 82→            @for (option of filteredOptions(); track option.id) {
 83→              <label
 84→                class="role-card__option"
 85→                [class.role-card__option--selected]="isSelected(option.id)"
 86→              >
 87→                <input
 88→                  [type]="
 89→                    questionType() === 'single_choice' ? 'radio' : 'checkbox'
 90→                  "
 91→                  [name]="'role-decision-' + card().roleId"
 92→                  [checked]="isSelected(option.id)"
 93→                  (change)="toggleOption(option)"
 94→                />
 95→                <span>{{ option.label }}</span>
 96→              </label>
 97→            }
 98→          }
 99→          @if (questionType() === "free_text") {
100→            <textarea
101→              class="role-card__textarea"
102→              [value]="freeText()"
103→              (input)="onTextInput($event)"
104→              placeholder="Enter your response..."
105→            ></textarea>
106→          }
107→          <div class="role-card__actions">
108→            <button
109→              uiButton
110→              variant="default"
111→              size="sm"
112→              (click)="onSubmit()"
113→              [disabled]="!canSubmit()"
114→            >
115→              Submit
116→            </button>
117→          </div>
118→        </div>
119→      }
120→
121→      <!-- Done State -->
122→      @if (card().status === "done") {
123→        <div class="role-card__done">Selected: {{ doneLabel() }}</div>
124→      }
125→    </div>
126→  `,
127→})
128→export class RoleCardComponent {
129→  readonly card = input.required<RoleCard>();
130→  readonly submitted = output<RoleCardSubmission>();
131→
132→  readonly selectedOptions = signal<string[]>([]);
133→  readonly freeText = signal("");
134→
135→  private readonly resetOnCardChange = effect(() => {
136→    this.card();
137→    untracked(() => {
138→      this.selectedOptions.set([]);
139→      this.freeText.set("");
140→    });
141→  });
142→
143→  readonly filteredOptions = computed<DecisionOption[]>(() => {
144→    const decision = this.card().decision;
145→    if (!decision) return [];
146→    const playerType = this.card().playerType;
147→    const roleId = this.card().roleId;
148→    if (playerType === "decision_maker") {
149→      return decision.options;
150→    }
151→    // advisor: COMMON options (no role) + own-role options
152→    return decision.options.filter((o) => !o.role || o.role === roleId);
153→  });
154→
155→  readonly badgeLabel = computed<string>(() => {
156→    const status = this.card().status;
157→    if (status === "intel") return "INJECT";
158→    if (status === "active") return "DECISION";
159→    return "DONE";
160→  });
161→
162→  readonly questionType = computed<string>(() => {
163→    return this.card().decision?.question_type ?? "free_text";
164→  });
165→
166→  readonly doneLabel = computed<string>(() => {
167→    const decision = this.card().decision;
168→    if (!decision) return "";
169→    const roleId = this.card().roleId;
170→    const recEntry = Object.entries(decision.recommendations).find(
171→      ([key]) => extractRecRoleId(key) === roleId,
172→    );
173→    const optionId = recEntry?.[1];
174→    if (!optionId) return "";
175→    return decision.options.find((o) => o.id === optionId)?.label ?? optionId;
176→  });
177→
178→  protected isSelected(optionId: string): boolean {
179→    return this.selectedOptions().includes(optionId);
180→  }
181→
182→  protected canSubmit(): boolean {
183→    if (this.questionType() === "free_text") {
184→      return this.freeText().trim().length > 0;
185→    }
186→    return this.selectedOptions().length > 0;
187→  }
188→
189→  protected toggleOption(option: DecisionOption): void {
190→    if (this.questionType() === "single_choice") {
191→      this.selectedOptions.set([option.id]);
192→    } else {
193→      const current = this.selectedOptions();
194→      if (current.includes(option.id)) {
195→        this.selectedOptions.set(current.filter((id) => id !== option.id));
196→      } else {
197→        this.selectedOptions.set([...current, option.id]);
198→      }
199→    }
200→  }
201→
202→  protected onTextInput(event: Event): void {
203→    if (!(event.target instanceof HTMLTextAreaElement)) return;
204→    const textarea = event.target;
205→    this.freeText.set(textarea.value);
206→  }
207→
208→  protected onSubmit(): void {
209→    this.submitted.emit({
210→      roleId: this.card().roleId,
211→      selectedOptions: this.selectedOptions(),
212→      freeText: this.freeText(),
213→    });
214→  }
215→}
