export function submitRoleRecommendation(
  api: DecisionApiService,
  exerciseId: number,
  decision: ActiveDecision,
  participantId: string,
  rec: RoleRecommendation,
): void {
  const optionId = rec.selectedOptions[0];
  if (!optionId) return;
  api
    .submitRecommendation(
      exerciseId,
      decision.id,
      optionId,
      participantId,
      rec.roleId,
    )
    .subscribe();
}

